import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { getTranslations } from "next-intl/server";

import { SharedConversation } from "@/components/chat/shared-conversation";
import { loadSharedConversation } from "@/actions/chat-share";

/**
 * `/share/[id]` — a conversation its owner published, readable by
 * anyone with the link. Outside the `(app)` group on purpose: no
 * session, no workspace. `noindex`, so a link that leaks does not also
 * get crawled. Per-request, since sharing can be switched off.
 */
export const dynamic = "force-dynamic";

interface SharePageProps {
  params: Promise<{ id: string; locale: string }>;
}

export async function generateMetadata({
  params,
}: SharePageProps): Promise<Metadata> {
  const { id } = await params;
  const t = await getTranslations("chat-share");
  const shared = await loadSharedConversation(id);
  return {
    title: shared?.title ?? t("title"),
    robots: { index: false, follow: false },
  };
}

export default async function SharePage({ params }: SharePageProps) {
  const { id } = await params;
  const shared = await loadSharedConversation(id);
  if (!shared) notFound();

  return (
    <SharedConversation
      conversationId={shared.id}
      title={shared.title}
      messages={shared.messages}
    />
  );
}

"use server";

/**
 * The public read of a shared conversation. No actor: the reader is
 * anyone with the link. What they get is decided by `sanitizeForShare`
 * (`@intelligo-dev/chat`) — the transcript minus reasoning, tool
 * details, provider metadata, transient parts and file URLs. A product
 * that wants a named tool's output on the page passes a policy here.
 */

import { sanitizeForShare, toUIMessages } from "@intelligo-dev/chat";
import type { UIMessage } from "ai";
import {
  getPublicConversation,
  getPublicMessages,
  isConversationServiceError,
} from "@intelligo-dev/core/conversations";

export type SharedConversation = {
  id: string;
  title: string | null;
  updatedAt: string;
  messages: UIMessage[];
};

export async function loadSharedConversation(
  id: string
): Promise<SharedConversation | null> {
  try {
    const conversation = await getPublicConversation(id);
    const rows = await getPublicMessages(id);
    return {
      id: conversation.id,
      title: conversation.title,
      updatedAt: conversation.updatedAt.toISOString(),
      messages: sanitizeForShare(toUIMessages(rows)),
    };
  } catch (error) {
    if (isConversationServiceError(error) && error.code === "not_found") {
      return null;
    }
    throw error;
  }
}

"use client";

/**
 * A shared conversation, read-only: the same message component the
 * chat page renders, with no composer, no actions and no edit. The
 * banner says what this is and offers the product.
 */

import { useTranslations } from "next-intl";
import type { UIMessage } from "ai";

import { MessageList } from "@/components/chat/message-list";
import { Button } from "@/components/ui/button";
import { Link } from "@/i18n/navigation";

interface SharedConversationProps {
  conversationId: string;
  title: string | null;
  messages: UIMessage[];
}

export function SharedConversation({
  conversationId,
  title,
  messages,
}: SharedConversationProps) {
  const t = useTranslations("chat-share");

  return (
    <div className="flex h-dvh flex-col">
      <header className="flex items-center justify-between gap-3 border-b px-4 py-3">
        <div className="min-w-0">
          <p className="text-xs text-muted-foreground">{t("readOnly")}</p>
          <h1 className="truncate text-sm font-medium">
            {title ?? t("untitled")}
          </h1>
        </div>
        <Button size="sm" render={<Link href="/chat" />} nativeButton={false}>
          {t("openApp")}
        </Button>
      </header>
      <MessageList
        conversationId={conversationId}
        messages={messages}
        isStreaming={false}
        readOnly
      />
    </div>
  );
}

{
  "title": "Shared conversation",
  "readOnly": "Shared conversation · read-only",
  "untitled": "Untitled conversation",
  "openApp": "Start your own"
}
